export const commands = {
	/** Hands over the channels the desktop's own events go through. */
	subscribe: (onProject: Channel<ProjectInfo | null>, onCanvas: Channel<CanvasEvent>, onJob: Channel<Job>, onDownload: Channel<Transfer>) => invoke<StartupState>("subscribe", { onProject, onCanvas, onJob, onDownload }),
	listProjects: () => invoke<ProjectSummary[]>("list_projects"),
	/** Creates a project and opens it. */
	createProject: (name: string) => invoke<null>("create_project", { name }),
	openProject: (name: string) => invoke<null>("open_project", { name }),
	/** Deletes a project, closing it first if it's the open one. */
	deleteProject: (name: string) => invoke<null>("delete_project", { name }),
	closeProject: () => invoke<null>("close_project"),
	getProject: () => invoke<ProjectInfo | null>("get_project"),
	/** The page the editor shows, with its layers. */
	getPage: () => invoke<Page | null>("get_page"),
	selectPage: (page: PageId) => invoke<null>("select_page", { page }),
	deletePages: (pages: PageId[]) => invoke<null>("delete_pages", { pages }),
	/** Moves a page to `index`, counted after it's taken out. */
	movePage: (page: PageId, index: number) => invoke<null>("move_page", { page, index }),
	/** The page as it renders, 256 pixels tall, as WebP. */
	getThumbnail: (page: PageId) => invoke<ArrayBuffer>("get_thumbnail", { page }),
	/** Shows, hides, or fades layers. */
	setVisibility: (layers: LayerId[], visible: boolean | null, opacity: number | null) => invoke<null>("set_visibility", { layers, visible, opacity }),
	deleteLayers: (layers: LayerId[]) => invoke<null>("delete_layers", { layers }),
	/** Moves a layer under `parent`, or to the page's top level, at `index`
	 *  counted after it's taken out. */
	moveLayer: (layer: LayerId, parent: LayerId | null, index: number) => invoke<null>("move_layer", { layer, parent, index }),
	setLocked: (layers: LayerId[], locked: boolean) => invoke<null>("set_locked", { layers, locked }),
	/** A text layer's text, or a block's translation. */
	setText: (layer: LayerId, text: string) => invoke<null>("set_text", { layer, text }),
	/** A block's source text, as OCR would have read it. */
	setSourceText: (layer: LayerId, text: string) => invoke<null>("set_source_text", { layer, text }),
	/** Merges `style`, a `TextStyle` patch, into each layer's lettering. */
	setStyle: (layers: LayerId[], style: Value) => invoke<null>("set_style", { layers, style }),
	/** A JSON Merge Patch of a layer's values, for the Inspector's frame, fit,
	 *  anchor, direction, and language. */
	updateLayer: (layer: LayerId, patch: Value) => invoke<null>("update_layer", { layer, patch }),
	undo: () => invoke<null>("undo"),
	redo: () => invoke<null>("redo"),
	/** Goes to the project as it was after `step` steps, as a click in
	 *  Photoshop's History panel does; 0 is the project as it opened. */
	goToStep: (step: number) => invoke<null>("go_to_step", { step }),
	/** Runs `stages` on `target`; each run's progress goes to the job channel.
	 *  `trace` is the caller's `sentry-trace` value, which the run continues. */
	process: (target: Target, stages: Stage[], trace: string | null) => invoke<RunId>("process", { target, stages, trace }),
	/** Stops every run, running and queued; what they finished stays. */
	stop: () => invoke<null>("stop"),
	getAgentStatus: () => invoke<AgentStatus>("get_agent_status"),
	/** Saves `[agent]`; the next run takes it. */
	saveAgentConfig: (config: AgentConfig) => invoke<AgentConfig>("save_agent_config", { config }),
	/** Runs `prompt` on the open project, in its conversation, and answers the
	 *  run's id at once. `trace` is the caller's `sentry-trace` value, which the
	 *  run continues. */
	runAgent: (prompt: string, onEvent: Channel<AgentEvent>, trace: string | null) => invoke<number>("run_agent", { prompt, onEvent, trace }),
	cancelAgent: (run: number) => invoke<null>("cancel_agent", { run }),
	/** Starts or stops serving the agent's tools over MCP, and answers the URL
	 *  while it serves. */
	setMcp: (enabled: boolean) => invoke<string | null>("set_mcp", { enabled }),
	getPreferences: () => invoke<Preferences>("get_preferences"),
	/** Saves every section, hands each to its owner, and answers them as the
	 *  file holds them now. */
	savePreferences: (preferences: Preferences) => invoke<Preferences>("save_preferences", { preferences }),
	/** Koharu's own models, and each vendor's that has a key or a sign-in. */
	getModels: () => invoke<ModelInfo[]>("get_models"),
	/** The vendors that take an API key, by rig's names, each with whether one
	 *  is stored. ChatGPT signs in instead, and its sign-in has the slot a key
	 *  would take. */
	getVendors: () => invoke<Vendor[]>("get_vendors"),
	/** Stores `vendor`'s API key, encrypted with the key the OS credential
	 *  store keeps, or forgets it for `None`. */
	setApiKey: (vendor: string, key: string | null) => invoke<null>("set_api_key", { vendor, key }),
	getFonts: () => invoke<FontFamily[]>("get_fonts"),
	/** `family`'s name set in it, as WebP. */
	getFontPreview: (family: string) => invoke<ArrayBuffer>("get_font_preview", { family }),
	/** Picks files or a folder and adds their pages after the project's last. */
	import: (source: ImportSource) => invoke<null>("import", { source }),
	/** Adds the pages of files dropped on the window. */
	importPaths: (paths: string[]) => invoke<null>("import_paths", { paths }),
	/** Picks where the open project's pages go, and writes them there. */
	export: (format: ExportFormat, labels: PsdLabels) => invoke<null>("export", { format, labels }),
	setCanvasViewport: (rect: ViewportRect) => invoke<null>("set_canvas_viewport", { rect }),
	setTool: (tool: Tool) => invoke<null>("set_tool", { tool }),
	setBrush: (brush: Brush) => invoke<null>("set_brush", { brush }),
	setColors: (colors: Colors) => invoke<null>("set_colors", { colors }),
	/** Fits the page in the canvas, as the fit shortcut does. */
	fitCanvas: () => invoke<null>("fit_canvas"),
	/** Zooms about the canvas's centre, `zoom` CSS pixels to a page pixel, as
	 *  the status bar's slider sets it. */
	setZoom: (zoom: number) => invoke<null>("set_zoom", { zoom }),
	/** The selection the Layers panel made. */
	selectLayers: (layers: LayerId[]) => invoke<null>("select_layers", { layers }),
};

